% Sparse leftovers after ADR 0369 (open item 337 and item 340's integer beside a sparse matrix; ADR
% 0374). Every row was measured in R2025b 25.2 (probes p7b_a, p7b_b, p7b_c, p7b_mat): the 1-by-1
% sparse matrix S(i, j) answers and a sparse matrix through the functions that read it as a dense
% array (shapes, statistics, rearrangements, casts, the logical verbs, num2cell), the refusals R2025b
% gives a sparse argument (string, char, interp1, histc, the bit functions, gamma, arrayfun),
% sparse(i, j, v) with subscripts of two classes, kron of a complex matrix, true/zeros(..., 'like', S)
% in S's class, an integer beside a sparse matrix (MATLAB:sparseInteger), and version 7.3 MAT-files
% of logical, single and complex sparse matrices saved and loaded.

% --- version 7.3 MAT-files: a logical, single or complex sparse matrix saved and loaded in its class -
csv_chk('m_v73_logical', 'f = [tempname ''.mat'']; L = sparse(logical([1 0; 0 1; 1 1])); save(f, ''L'', ''-v7.3''); r = load(f); delete(f); v = r.L;', 17, 'exact');
csv_chk('m_v73_logical_whos', 'f = [tempname ''.mat'']; L = sparse(logical([1 0; 0 1; 1 1])); save(f, ''L'', ''-v7.3''); w = whos(''-file'', f); delete(f); v = sprintf(''%s %d %d %s'', w.class, w.sparse, w.complex, mat2str(w.size));', 17, 'exact');
csv_chk('m_v73_logical_empty', 'f = [tempname ''.mat'']; E = sparse(false(2, 3)); save(f, ''E'', ''-v7.3''); r = load(f); delete(f); v = r.E;', 17, 'exact');
csv_chk('m_v73_single', 'f = [tempname ''.mat'']; F = sparse(single([1.5 0 2; 0 0 -3])); save(f, ''F'', ''-v7.3''); r = load(f); delete(f); v = r.F;', 17, 'exact');
csv_chk('m_v73_single_whos', 'f = [tempname ''.mat'']; F = sparse(single([1.5 0 2; 0 0 -3])); save(f, ''F'', ''-v7.3''); w = whos(''-file'', f); delete(f); v = sprintf(''%s %d %d %s'', w.class, w.sparse, w.complex, mat2str(w.size));', 17, 'exact');
csv_chk('m_v73_complex', 'f = [tempname ''.mat'']; C = sparse([1+2i 0; 0 3; -1i 0]); save(f, ''C'', ''-v7.3''); r = load(f); delete(f); v = r.C;', 17, 'exact');
csv_chk('m_v73_complex_whos', 'f = [tempname ''.mat'']; C = sparse([1+2i 0; 0 3; -1i 0]); save(f, ''C'', ''-v7.3''); w = whos(''-file'', f); delete(f); v = sprintf(''%s %d %d %s'', w.class, w.sparse, w.complex, mat2str(w.size));', 17, 'exact');
csv_chk('m_v73_complex_single', 'f = [tempname ''.mat'']; C = sparse(single([1+2i 0 4])); save(f, ''C'', ''-v7.3''); r = load(f); delete(f); v = r.C;', 17, 'exact');
csv_chk('m_v73_complex_flag', 'f = [tempname ''.mat'']; C = sparse(complex([1 0 2], 0)); save(f, ''C'', ''-v7.3''); r = load(f); delete(f); v = r.C;', 17, 'exact');
csv_chk('m_v73_double', 'f = [tempname ''.mat'']; D = sparse([0 2; 3 0]); save(f, ''D'', ''-v7.3''); r = load(f); delete(f); v = r.D;', 17, 'exact');
csv_chk('m_v73_cell', 'f = [tempname ''.mat'']; q = {sparse(logical([1 0])), sparse(single(2))}; save(f, ''q'', ''-v7.3''); r = load(f); delete(f); v = r.q{2} + r.q{1};', 17, 'exact');
